class Widget {
public:
  // Public primary member template
  template<typename T>
  void processPointer(T* ptr) { /* ... */ }

private:
  // This is an attempt to use the C++98 idiom.
  // It will NOT compile!
  // Specializations of member templates cannot be in class scope.
  template<>
  void processPointer<void>(void*); // ERROR!
};

// Even at namespace scope, you can't change the access level.
// The following would also be an error if 'private' could be specified here.
template<>
void Widget::processPointer<void>(void*) = delete; // This is the correct C++11 way.
